    let item = items.get(n).select("li > a");
    for (let i = 0; i < item.size(); i++) {
        let a = item.get(i);
        let title = a.text();
        let href = a.attr("href");
        let source  = "播放路线  " + (n + 1);
        plist.push({
            title: title,
            url: href,
            source: source
        });
    }
}

plist;

