ruleToc.chapterName:
$.chaptername
@js:
result=result.replace(/^\s+/,'');
vip='{{$.isvip}}'!='0';
lock='{{$.islock}}'!='0';
type='{{$.chaptertype}}'=='1';
num=!type?'{{$.chapterid}}、':'';
if(result.match(/[一二三四五六七八九十百千万\d]+\s*章|^\d+[、\.\s]|chapter\s*\d+/i)){
num=''
}else{num=num}
result=type?'📖 '+result+' 📖':result;
v=vip?'✿ ':'';l=lock?'[此章节已锁]':'';
result=v+num+result+l;

ruleToc.chapterUrl:
$.chapterid
@js:
cookie=java.get('cookie');
vip='{{$.isvip}}'!='0';
type='{{$.chaptertype}}'=='1';
if(!vip){
if(!type){
result='https://app-cdn.jjwxc.net/androidapi/chapterContent?novelId='+baseUrl.match(/novelId=(\d+)/)[1]+'&chapterId='+result
}else{
chaptername="{{$.chaptername}}";
result='http://www.baidu.com?wd='+result+book.name+'/'+chaptername}
}else{result="http://app.jjwxc.org/androidapi/chapterContent?novelId="+baseUrl.match(/novelId=(\d+)/)[1]+'&versionCode=191&token='+cookie+'&chapterId='+result}

